#!/usr/bin/env python3
import sys, os, re, json, csv, base64, urllib.parse, copy, configparser
from io import StringIO
import xml.etree.ElementTree as ET

VERSION = 'v4.52.5'

# ----------------------------- helpers -----------------------------
class YQError(Exception):
    pass

def eprint(*args):
    print(*args, file=sys.stderr)

def is_int(s):
    return re.fullmatch(r'[+-]?\d+', str(s)) is not None

def is_num_str(s):
    return re.fullmatch(r'[+-]?(?:\d+\.\d*|\d*\.\d+|\d+)(?:[eE][+-]?\d+)?', str(s)) is not None

def split_top(s, sep):
    out=[]; cur=[]; depth=0; quote=None; esc=False
    i=0
    while i < len(s):
        c=s[i]
        if quote:
            cur.append(c)
            if esc:
                esc=False
            elif c=='\\':
                esc=True
            elif c==quote:
                quote=None
        else:
            if c in ('"',"'"):
                quote=c; cur.append(c)
            elif c in '[{(':
                depth+=1; cur.append(c)
            elif c in ']})':
                depth-=1; cur.append(c)
            elif c==sep and depth==0:
                out.append(''.join(cur).strip()); cur=[]
            else:
                cur.append(c)
        i+=1
    out.append(''.join(cur).strip())
    return out

def find_top_op(s, ops):
    depth=0; quote=None; esc=False
    # scan left-to-right; callers order by precedence as needed
    i=0
    while i < len(s):
        c=s[i]
        if quote:
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
            i+=1; continue
        if c in ('"',"'"):
            quote=c; i+=1; continue
        if c in '[{(':
            depth+=1; i+=1; continue
        if c in ']})':
            depth-=1; i+=1; continue
        if depth==0:
            for op in ops:
                if s.startswith(op, i):
                    return i, op
        i+=1
    return -1, None

def strip_outer_parens(s):
    s=s.strip()
    while s.startswith('(') and s.endswith(')'):
        inner=s[1:-1]
        if balanced(inner):
            s=inner.strip()
        else:
            break
    return s

def balanced(s):
    depth=0; quote=None; esc=False
    for c in s:
        if quote:
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
        else:
            if c in ('"',"'"): quote=c
            elif c in '[{(': depth+=1
            elif c in ']})':
                depth-=1
                if depth<0: return False
    return depth==0 and quote is None

# ----------------------------- YAML-ish parser -----------------------------
def strip_comment(line):
    quote=None; esc=False
    for i,c in enumerate(line):
        if quote:
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
        else:
            if c in ('"',"'"): quote=c
            elif c=='#' and (i==0 or line[i-1].isspace()):
                return line[:i].rstrip()
    return line.rstrip('\n\r')

def split_docs(text):
    docs=[]; cur=[]
    for raw in text.splitlines():
        if raw.strip() == '---':
            docs.append('\n'.join(cur)); cur=[]
        elif raw.strip() == '...':
            docs.append('\n'.join(cur)); cur=[]
        else:
            cur.append(raw)
    if cur or not docs:
        docs.append('\n'.join(cur))
    return docs

def prep_lines(text):
    lines=[]
    for raw in text.splitlines():
        if not raw.strip():
            continue
        st=raw.lstrip(' ')
        if st.startswith('#'):
            continue
        line=strip_comment(raw)
        if not line.strip():
            continue
        indent=len(line)-len(line.lstrip(' '))
        lines.append((indent,line.lstrip(' ')))
    return lines

def parse_scalar(s):
    s=s.strip()
    if s == '':
        return ''
    if s in ('null','Null','NULL','~'):
        return None
    if s == 'true' or s == 'True' or s == 'TRUE':
        return True
    if s == 'false' or s == 'False' or s == 'FALSE':
        return False
    if (s.startswith('"') and s.endswith('"')) or (s.startswith("'") and s.endswith("'")):
        try:
            if s[0]=='"':
                return json.loads(s)
            return s[1:-1].replace("''", "'")
        except Exception:
            return s[1:-1]
    if s.startswith('[') and s.endswith(']'):
        return parse_inline_list(s[1:-1])
    if s.startswith('{') and s.endswith('}'):
        return parse_inline_map(s[1:-1])
    if re.fullmatch(r'[+-]?\d+', s):
        try: return int(s)
        except Exception: pass
    if re.fullmatch(r'[+-]?(?:\d+\.\d*|\d*\.\d+)(?:[eE][+-]?\d+)?', s) or re.fullmatch(r'[+-]?\d+[eE][+-]?\d+', s):
        try: return float(s)
        except Exception: pass
    return s

def parse_inline_list(body):
    if body.strip()=='': return []
    return [parse_scalar(p) for p in split_top(body, ',')]

def parse_inline_map(body):
    d={}
    if body.strip()=='': return d
    for part in split_top(body, ','):
        k,v=split_key_value(part)
        if k is None:
            continue
        d[parse_key(k)] = parse_scalar(v)
    return d

def split_key_value(s):
    depth=0; quote=None; esc=False
    for i,c in enumerate(s):
        if quote:
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
        else:
            if c in ('"',"'"): quote=c
            elif c in '[{(': depth+=1
            elif c in ']})': depth-=1
            elif c==':' and depth==0:
                return s[:i].strip(), s[i+1:].strip()
    return None, None

def parse_key(k):
    k=k.strip()
    if (k.startswith('"') and k.endswith('"')) or (k.startswith("'") and k.endswith("'")):
        return str(parse_scalar(k))
    return k

def parse_yaml_doc(text):
    # JSON is valid YAML for common inputs; try it first when it looks JSON-ish.
    st=text.strip()
    if st == '':
        return None
    if st[0] in '[{':
        try: return json.loads(st)
        except Exception: pass
        try: return parse_scalar(st)
        except Exception: pass
    lines=prep_lines(text)
    if not lines:
        return None
    val, idx=parse_block(lines,0,lines[0][0])
    return val

def parse_block(lines, idx, indent):
    if idx>=len(lines): return None, idx
    if lines[idx][0] < indent: return None, idx
    if lines[idx][1].startswith('- ') and lines[idx][0]==indent:
        return parse_sequence(lines, idx, indent)
    return parse_mapping(lines, idx, indent)

def parse_mapping(lines, idx, indent):
    d={}
    while idx < len(lines):
        ind, txt=lines[idx]
        if ind < indent: break
        if ind > indent:
            break
        if txt.startswith('- '): break
        k,v = split_key_value(txt)
        if k is None:
            idx += 1; continue
        key=parse_key(k)
        if v == '' or v in ('|','>','|-','>-','|+','>+'):
            if v.startswith('|') or v.startswith('>'):
                idx += 1
                block=[]
                while idx < len(lines) and lines[idx][0] > indent:
                    block.append(lines[idx][1])
                    idx += 1
                sep='\n' if v.startswith('|') else ' '
                d[key]=sep.join(block)
            else:
                idx += 1
                if idx < len(lines) and lines[idx][0] > indent:
                    child, idx = parse_block(lines, idx, lines[idx][0])
                    d[key]=child
                else:
                    d[key]=None
        else:
            d[key]=parse_scalar(v)
            idx += 1
    return d, idx

def parse_sequence(lines, idx, indent):
    arr=[]
    while idx < len(lines):
        ind, txt=lines[idx]
        if ind != indent or not txt.startswith('- '):
            break
        content=txt[2:].strip()
        if content == '':
            idx += 1
            if idx < len(lines) and lines[idx][0] > indent:
                child, idx = parse_block(lines, idx, lines[idx][0])
                arr.append(child)
            else:
                arr.append(None)
        else:
            k,v=split_key_value(content)
            if k is not None and not (content.startswith('{') or content.startswith('[')):
                item={parse_key(k): parse_scalar(v) if v!='' else None}
                idx += 1
                if v=='':
                    if idx < len(lines) and lines[idx][0] > indent:
                        child, idx = parse_block(lines, idx, lines[idx][0])
                        item[parse_key(k)] = child
                # consume following mapping entries indented under this item
                while idx < len(lines) and lines[idx][0] > indent:
                    subind, subtxt=lines[idx]
                    if subtxt.startswith('- ') and subind==indent+2:
                        break
                    kk,vv=split_key_value(subtxt)
                    if kk is None: break
                    key=parse_key(kk)
                    if vv=='':
                        idx += 1
                        if idx < len(lines) and lines[idx][0] > subind:
                            child, idx = parse_block(lines, idx, lines[idx][0])
                        else:
                            child=None
                        item[key]=child
                    else:
                        item[key]=parse_scalar(vv); idx += 1
                arr.append(item)
            else:
                arr.append(parse_scalar(content)); idx += 1
    return arr, idx

def parse_yaml(text):
    return [parse_yaml_doc(d) for d in split_docs(text)]

# ----------------------------- other formats -----------------------------
def parse_json_text(text):
    st=text.strip()
    if st=='': return [None]
    # multiple JSON docs line-by-line if whole file fails
    try: return [json.loads(st)]
    except Exception:
        docs=[]
        for line in text.splitlines():
            if line.strip(): docs.append(json.loads(line))
        return docs or [None]

def auto_parse_cell(s):
    # CSV auto parse via yaml/json-style scalar
    return parse_scalar(s)

def parse_csv_text(text, sep=','):
    rdr=csv.reader(StringIO(text), delimiter=sep)
    rows=list(rdr)
    if not rows: return [[]]
    header=rows[0]
    out=[]
    for row in rows[1:]:
        if not row: continue
        d={}
        for i,h in enumerate(header):
            d[h]=auto_parse_cell(row[i]) if i < len(row) else ''
        out.append(d)
    return [out]

def set_path(root, parts, value):
    if root is None:
        root=[] if parts and isinstance(parts[0], int) else {}
    cur=root
    for i,p in enumerate(parts):
        last=i==len(parts)-1
        nxt = parts[i+1] if not last else None
        if isinstance(p, int):
            if not isinstance(cur, list):
                # cannot replace parent by reference here except caller ensures
                return root
            while len(cur) <= p: cur.append(None)
            if last:
                cur[p]=value
            else:
                if cur[p] is None or not isinstance(cur[p], (dict,list)):
                    cur[p] = [] if isinstance(nxt,int) else {}
                cur=cur[p]
        else:
            if not isinstance(cur, dict): return root
            if last:
                cur[p]=value
            else:
                if p not in cur or cur[p] is None or not isinstance(cur[p], (dict,list)):
                    cur[p] = [] if isinstance(nxt,int) else {}
                cur=cur[p]
    return root

def parse_props_text(text):
    root={}
    for raw in text.splitlines():
        line=raw.strip()
        if not line or line.startswith('#') or line.startswith('!'): continue
        if '=' in line:
            k,v=line.split('=',1)
        elif ':' in line:
            k,v=line.split(':',1)
        else:
            continue
        key=k.strip(); val=v.strip()
        parts=[]
        for p in key.split('.'):
            if p.isdigit(): parts.append(int(p))
            elif re.fullmatch(r'.+\[\d+\]', p):
                name=p[:p.rfind('[')]; idx=int(p[p.rfind('[')+1:-1]); parts.extend([name,idx])
            else: parts.append(p)
        # create arrays when numeric next: conversion pass simpler
        root=set_path_smart(root, parts, val)
    return [root]

def set_path_smart(root, parts, value):
    # rebuild with dict/list awareness
    def rec(cur, ps):
        if not ps: return value
        p=ps[0]
        if isinstance(p,int):
            arr = cur if isinstance(cur,list) else []
            while len(arr)<=p: arr.append(None)
            arr[p]=rec(arr[p], ps[1:])
            return arr
        else:
            d = cur if isinstance(cur,dict) else {}
            d[p]=rec(d.get(p), ps[1:])
            return d
    return rec(root, parts)

def parse_ini_text(text):
    root={}; section=None
    for raw in text.splitlines():
        line=raw.strip()
        if not line or line.startswith(';') or line.startswith('#'): continue
        if line.startswith('[') and line.endswith(']'):
            section=line[1:-1].strip(); root.setdefault(section,{})
        elif '=' in line or ':' in line:
            sep='=' if '=' in line else ':'
            k,v=line.split(sep,1); k=k.strip(); v=v.strip()
            if section: root.setdefault(section,{})[k]=v
            else: root[k]=v
    return [root]

def parse_toml_text(text):
    root={}; cur=root
    for raw in text.splitlines():
        line=strip_comment(raw).strip()
        if not line: continue
        if line.startswith('[') and line.endswith(']'):
            parts=[p.strip() for p in line[1:-1].split('.')]
            cur=root
            for p in parts:
                cur=cur.setdefault(p,{})
        elif '=' in line:
            k,v=line.split('=',1); cur[k.strip()]=parse_scalar(v.strip())
    return [root]

def elem_to_obj(el):
    children=list(el)
    attrs={'+@'+k:v for k,v in el.attrib.items()}
    text=(el.text or '').strip()
    if not children and not attrs:
        return text
    d={}
    if text:
        d['+content']=text
    for k,v in attrs.items(): d[k]=v
    groups={}
    for ch in children:
        groups.setdefault(ch.tag,[]).append(elem_to_obj(ch))
    for k,vals in groups.items():
        d[k]=vals[0] if len(vals)==1 else vals
    return d

def parse_xml_text(text):
    root_el=ET.fromstring(text.strip())
    return [{root_el.tag: elem_to_obj(root_el)}]

def parse_input(text, fmt, filename=None):
    f=(fmt or 'auto').lower()
    aliases={'y':'yaml','a':'auto','j':'json','p':'props','c':'csv','t':'tsv','x':'xml','h':'hcl','l':'lua','i':'ini'}
    f=aliases.get(f,f)
    if f=='auto':
        ext=os.path.splitext(filename or '')[1].lower()
        f={'.json':'json','.csv':'csv','.tsv':'tsv','.xml':'xml','.properties':'props','.props':'props','.toml':'toml','.ini':'ini'}.get(ext,'yaml')
    if f in ('yaml','kyaml'):
        return parse_yaml(text)
    if f=='json': return parse_json_text(text)
    if f=='csv': return parse_csv_text(text, ',')
    if f=='tsv': return parse_csv_text(text, '\t')
    if f in ('props','properties'): return parse_props_text(text)
    if f=='xml': return parse_xml_text(text)
    if f=='ini': return parse_ini_text(text)
    if f in ('toml','hcl'): return parse_toml_text(text)
    if f=='base64': return [base64.b64decode(text.strip()).decode()]
    if f=='uri': return [urllib.parse.unquote_plus(text.strip())]
    return parse_yaml(text)

# ----------------------------- output -----------------------------
def scalar_to_string(v, quote_for_yaml=False):
    if v is None: return 'null'
    if v is True: return 'true'
    if v is False: return 'false'
    if isinstance(v,(int,float)): return str(v).lower()
    s=str(v)
    if quote_for_yaml:
        if s=='' or s in ('true','false','null','Null','NULL','~') or is_num_str(s) or ': ' in s or ' #' in s or s[0:1] in ['@','`','&','*','!','|','>','{','}','[',']',',']:
            return json.dumps(s)
    return s

def yaml_lines(v, indent=0, step=2):
    sp=' '*indent
    if isinstance(v, dict):
        if not v: return [sp+'{}']
        lines=[]
        for k,val in v.items():
            key=str(k)
            if isinstance(val,(dict,list)):
                if isinstance(val, (dict,list)) and len(val)==0:
                    lines.append(f'{sp}{key}: ' + ('{}' if isinstance(val,dict) else '[]'))
                else:
                    lines.append(f'{sp}{key}:')
                    lines.extend(yaml_lines(val, indent+step, step))
            else:
                lines.append(f'{sp}{key}: {scalar_to_string(val, True)}')
        return lines
    if isinstance(v, list):
        if not v: return [sp+'[]']
        lines=[]
        for item in v:
            if isinstance(item, dict):
                if not item:
                    lines.append(sp+'- {}')
                else:
                    first=True
                    for k,val in item.items():
                        if first:
                            if isinstance(val,(dict,list)):
                                lines.append(f'{sp}- {k}:')
                                lines.extend(yaml_lines(val, indent+step, step))
                            else:
                                lines.append(f'{sp}- {k}: {scalar_to_string(val, True)}')
                            first=False
                        else:
                            if isinstance(val,(dict,list)):
                                lines.append(f'{sp}{" "*step}{k}:')
                                lines.extend(yaml_lines(val, indent+2*step, step))
                            else:
                                lines.append(f'{sp}{" "*step}{k}: {scalar_to_string(val, True)}')
            elif isinstance(item, list):
                lines.append(sp+'-')
                lines.extend(yaml_lines(item, indent+step, step))
            else:
                lines.append(f'{sp}- {scalar_to_string(item, True)}')
        return lines
    return [sp+scalar_to_string(v, False)]

def dump_yaml(v, indent=2):
    return '\n'.join(yaml_lines(v,0,indent))

def flatten(v, prefix='', sep='.'):
    rows=[]
    if isinstance(v, dict):
        for k,val in v.items():
            p=f'{prefix}{sep}{k}' if prefix else str(k)
            rows.extend(flatten(val,p,sep))
    elif isinstance(v, list):
        for i,val in enumerate(v):
            p=f'{prefix}{sep}{i}' if prefix else str(i)
            rows.extend(flatten(val,p,sep))
    else:
        rows.append((prefix, scalar_to_string(v)))
    return rows

def dump_props(v, sepstr=' = '):
    return '\n'.join(k+sepstr+val for k,val in flatten(v,'.'.join([]),'.'))

def dump_shell(v, keysep='_'):
    return '\n'.join(k.replace('.',keysep)+'='+shell_quote_value(val) for k,val in flatten(v,'','.'))

def shell_quote_value(s):
    s=str(s)
    if re.fullmatch(r'[A-Za-z0-9_./:@%+-]*', s): return s
    return "'" + s.replace("'", "'\\''") + "'"

def dump_csv(v, sep=','):
    arr=v if isinstance(v,list) else [v]
    if not arr: return ''
    if all(isinstance(x,dict) for x in arr):
        headers=[]
        for row in arr:
            for k in row.keys():
                if k not in headers: headers.append(k)
        sio=StringIO(); w=csv.writer(sio, delimiter=sep, lineterminator='\n')
        w.writerow(headers)
        for row in arr:
            w.writerow([scalar_to_string(row.get(h,'')) for h in headers])
        return sio.getvalue().rstrip('\n')
    sio=StringIO(); w=csv.writer(sio, delimiter=sep, lineterminator='\n')
    for item in arr: w.writerow([scalar_to_string(item)])
    return sio.getvalue().rstrip('\n')

def xml_escape(s):
    return str(s).replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')

def dump_xml(v, name=None, indent=0):
    sp=' '*indent
    lines=[]
    if name is None:
        if isinstance(v,dict):
            for k,val in v.items(): lines.extend(dump_xml(val,k,indent))
        elif isinstance(v,list):
            for item in v: lines.extend(dump_xml(item,'item',indent))
        else:
            lines.append(xml_escape(scalar_to_string(v)))
        return lines
    if isinstance(v,list):
        for item in v: lines.extend(dump_xml(item,name,indent))
    elif isinstance(v,dict):
        attrs=''; content=None; children=[]
        for k,val in v.items():
            if str(k).startswith('+@'):
                attrs += f' {k[2:]}="{xml_escape(val)}"'
            elif k=='+content':
                content=scalar_to_string(val)
            else:
                children.extend(dump_xml(val,k,indent+2))
        if children:
            lines.append(f'{sp}<{name}{attrs}>')
            if content: lines.append(' '*(indent+2)+xml_escape(content))
            lines.extend(children)
            lines.append(f'{sp}</{name}>')
        else:
            text=xml_escape(content or '')
            lines.append(f'{sp}<{name}{attrs}>{text}</{name}>')
    else:
        lines.append(f'{sp}<{name}>{xml_escape(scalar_to_string(v))}</{name}>')
    return lines

def lua_val(v, level=0):
    tab='\t'*level
    if isinstance(v,dict):
        lines=['{']
        for k,val in v.items():
            rendered=lua_val(val, level+1)
            if '\n' in rendered:
                lines.append('\t'*(level+1)+f'[{json.dumps(str(k))}] = '+rendered+';')
            else:
                lines.append('\t'*(level+1)+f'[{json.dumps(str(k))}] = {rendered};')
        lines.append(tab+'}')
        return '\n'.join(lines)
    if isinstance(v,list):
        lines=['{']
        for item in v:
            rendered=lua_val(item, level+1)
            lines.append('\t'*(level+1)+rendered+',')
        lines.append(tab+'}')
        return '\n'.join(lines)
    if isinstance(v,str): return json.dumps(v)
    if v is True: return 'true'
    if v is False: return 'false'
    if v is None: return 'nil'
    return str(v)

def dump_one(v, fmt, indent=2, unwrap=True, props_sep=' = ', shell_sep='_'):
    f=fmt.lower()
    aliases={'y':'yaml','j':'json','p':'props','c':'csv','t':'tsv','x':'xml','s':'shell','l':'lua','i':'ini'}
    f=aliases.get(f,f)
    if f in ('yaml','kyaml'):
        if not isinstance(v,(dict,list)) and unwrap:
            return scalar_to_string(v, False)
        return dump_yaml(v, indent)
    if f=='json': return json.dumps(v, indent=indent)
    if f in ('props','properties','ini'): return dump_props(v, props_sep)
    if f=='shell': return dump_shell(v, shell_sep)
    if f=='csv': return dump_csv(v, ',')
    if f=='tsv': return dump_csv(v, '\t')
    if f=='xml': return '\n'.join(dump_xml(v))
    if f=='base64': return base64.b64encode(scalar_to_string(v).encode()).decode()
    if f=='uri': return urllib.parse.quote_plus(scalar_to_string(v))
    if f=='lua': return 'return '+lua_val(v)+';'
    return dump_yaml(v, indent)

# ----------------------------- expression evaluation -----------------------------
def parse_path(path):
    s=path.strip()
    if s == '.': return []
    if not s.startswith('.'):
        raise YQError('bad expression')
    parts=[]; i=1; key=''
    while i < len(s):
        c=s[i]
        if c=='.':
            if key!='': parts.append(key); key=''
            i+=1
        elif c=='[':
            if key!='': parts.append(key); key=''
            j=s.find(']',i)
            if j<0: raise YQError('bad expression, could not find matching `]`')
            inside=s[i+1:j].strip()
            if inside=='': parts.append('*')
            elif (inside.startswith('"') and inside.endswith('"')) or (inside.startswith("'") and inside.endswith("'")):
                parts.append(str(parse_scalar(inside)))
            elif re.fullmatch(r'-?\d+', inside): parts.append(int(inside))
            else: parts.append(inside)
            i=j+1
        else:
            key+=c; i+=1
