    if 'ireduce' in expr and '*' in expr and isinstance(data, list) and getattr(opts,'eval_all',False):
        acc={}
        for d in data: acc=deep_merge(acc,d)
        return [acc]
    stages=split_top(expr, '|')
    vals=[data]
    for st in stages:
        if st=='': continue
        nextvals=[]
        for v in vals:
            nextvals.extend(eval_stage(st, v, opts))
        vals=nextvals
    return vals

def eval_stage(expr, data, opts=None):
    expr=strip_outer_parens(expr.strip())
