    pos,op=find_assignment(expr)
    if pos>=0:
        left=expr[:pos].strip(); right=expr[pos+1:].strip()
        vals=eval_expr(right, data, opts)
        val=vals[0] if vals else None
        d=copy.deepcopy(data)
        return [assign_path(d, left, val)]
    # comparisons
    for ops in [['==','!=','>=','<='], ['>','<']]:
        pos,op=find_top_op(expr, ops)
        if pos>=0:
            a=first(eval_expr(expr[:pos], data, opts)); b=first(eval_expr(expr[pos+len(op):], data, opts))
            return [compare(a,b,op)]
    # addition/subtraction after comparisons
    pos,op=find_top_arith(expr, ['+','-'])
    if pos>=0:
        a=first(eval_expr(expr[:pos], data, opts)); b=first(eval_expr(expr[pos+1:], data, opts))
        try:
            if op=='+': return [a+b]
            return [a-b]
        except Exception:
            return [str(a)+str(b) if op=='+' else None]
    pos,op=find_top_arith(expr, ['*','/'])
    if pos>=0:
        a=first(eval_expr(expr[:pos], data, opts)); b=first(eval_expr(expr[pos+1:], data, opts))
        if op=='*':
            if isinstance(a,dict) and isinstance(b,dict): return [deep_merge(a,b)]
            try: return [a*b]
            except Exception: return [None]
        else:
            try: return [a/b]
            except Exception: return [None]
    # functions/stages
    if expr=='length':
        return [len(data) if data is not None and hasattr(data,'__len__') else 0]
    if expr=='keys':
        if isinstance(data,dict): return [list(data.keys())]
        if isinstance(data,list): return [list(range(len(data)))]
        return [[]]
    if expr.startswith('select(') and expr.endswith(')'):
        cond=first(eval_expr(expr[7:-1], data, opts))
        return [data] if truthy(cond) else []
    if expr.startswith('map(') and expr.endswith(')'):
        inner=expr[4:-1]
        if isinstance(data,list): return [[first(eval_expr(inner, item, opts)) for item in data]]
        return [[]]
    if expr.startswith('has(') and expr.endswith(')'):
        key=first(eval_expr(expr[4:-1], data, opts))
        if isinstance(data,dict): return [str(key) in data]
        if isinstance(data,list) and isinstance(key,int): return [0<=key<len(data)]
        return [False]
    if expr.startswith('del(') and expr.endswith(')'):
        return [delete_path(data, expr[4:-1].strip())]
    if expr.startswith('load(') and expr.endswith(')'):
        fn=first(eval_expr(expr[5:-1], data, opts))
        with open(fn,'r') as f: txt=f.read()
        fmt='auto'
        return [parse_input(txt, fmt, fn)[0]]
    if expr.startswith('strenv(') and expr.endswith(')'):
        name=expr[7:-1].strip()
        return [os.environ.get(name,'')]
    if expr.startswith('env(') and expr.endswith(')'):
        name=expr[4:-1].strip()
        return [parse_scalar(os.environ.get(name,''))]
    # collection/literals
    if expr.startswith('[') and expr.endswith(']'):
        inner=expr[1:-1].strip()
        if inner=='': return [[]]
        # JSON/YAML literal if comma separated and not an expression-ish collection
        if '|' not in inner and not inner.lstrip().startswith('.') and ',' in inner:
            return [[first(eval_expr(p, data, opts)) for p in split_top(inner, ',')]]
        if '|' not in inner and not inner.lstrip().startswith('.'):
            try: return [parse_scalar(expr)]
            except Exception: pass
        return [eval_expr(inner, data, opts)]
    if expr.startswith('{') and expr.endswith('}'):
        # yq requires quoted JSON-like keys for this simplified implementation
        try: return [json.loads(expr)]
        except Exception:
            return [parse_inline_map(expr[1:-1])]
    if (expr.startswith('"') and expr.endswith('"')) or (expr.startswith("'") and expr.endswith("'")):
        return [parse_scalar(expr)]
    if expr in ('true','false','null') or is_num_str(expr):
        return [parse_scalar(expr)]
    if expr=='.': return [data]
    if expr.startswith('.'):
        return get_path_values(data, parse_path(expr))
    # bare env variable? string fallback
    return [expr]

def first(vals):
    if isinstance(vals, list): return vals[0] if vals else None
    return vals

def truthy(v):
    return not (v is False or v is None)

def compare(a,b,op):
    if op=='==': return a==b
    if op=='!=': return a!=b
    try:
        if op=='>': return a>b
        if op=='<': return a<b
        if op=='>=': return a>=b
        if op=='<=': return a<=b
    except Exception:
        return False

def find_assignment(s):
    depth=0; quote=None; esc=False
    for i,c in enumerate(s):
        if quote:
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
        else:
            if c in ('"',"'"): quote=c
            elif c in '[{(': depth+=1
            elif c in ']})': depth-=1
            elif c=='=' and depth==0:
                prev=s[i-1] if i>0 else ''; nxt=s[i+1] if i+1<len(s) else ''
                if prev not in ['=','!','<','>'] and nxt!='=':
                    return i,'='
    return -1,None

def find_top_arith(s, ops):
    depth=0; quote=None; esc=False
    for i in range(len(s)-1, -1, -1):
        c=s[i]
        if quote:
            # reverse scan quote handling is hard; use forward collect positions instead
            pass
    depth=0; quote=None; esc=False; found=[]
    for i,c in enumerate(s):
        if quote:
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
        else:
            if c in ('"',"'"): quote=c
            elif c in '[{(': depth+=1
            elif c in ']})': depth-=1
            elif depth==0 and c in ops:
                if c in '+-' and (i==0 or s[i-1] in ' ([{:+-*/'):
                    continue
                found.append((i,c))
    return found[-1] if found else (-1,None)

