# Pipe from STDIN
## use '-' as a filename to pipe from STDIN
cat file2.yml | yq e '.a.b' file1.yml - file3.yml

Flags:
  -h, --help   help for eval
'''

def completion(shell):
    if shell in ('bash','zsh','fish','powershell'):
        return f'# {shell} completion for yq\n'
    raise YQError('unknown shell')

def parse_args(argv):
    opts=Opts(); opts.input_format='auto'; opts.output_format='auto'; opts.indent=2; opts.inplace=False
    opts.null_input=False; opts.no_doc=False; opts.nul=False; opts.exit_status=False; opts.unwrap=True
    opts.expression=None; opts.from_file=None; opts.eval_all=False; opts.props_sep=' = '; opts.shell_sep='_'
    opts.command=None; opts.files=[]; positionals=[]
    i=0
    if argv and argv[0] in ('eval','e','eval-all','ea'):
        opts.command=argv[0]; opts.eval_all=argv[0] in ('eval-all','ea'); i=1
    elif argv and argv[0]=='help':
        opts.command='help'; positionals=argv[1:]; i=len(argv)
    elif argv and argv[0]=='completion':
        opts.command='completion'; positionals=argv[1:]; i=len(argv)
    while i < len(argv):
        a=argv[i]
        def needval():
            nonlocal i
            if i+1>=len(argv): raise YQError('flag needs an argument: '+a)
            i+=1; return argv[i]
        if a in ('-h','--help'):
            opts.command='helpflag'
        elif a in ('-V','--version'):
            opts.version=True
        elif a in ('-i','--inplace'):
            opts.inplace=True
        elif a in ('-n','--null-input'):
            opts.null_input=True
        elif a in ('-N','--no-doc'):
            opts.no_doc=True
        elif a in ('-0','--nul-output'):
            opts.nul=True
        elif a in ('-e','--exit-status'):
            opts.exit_status=True
        elif a in ('-P','--prettyPrint','--prettyprint'):
            pass
        elif a in ('-C','--colors','-M','--no-colors','-v','--verbose','--debug-node-info','--csv-auto-parse','--tsv-auto-parse','--xml-keep-namespace','--xml-raw-token','--xml-skip-directives','--xml-skip-proc-inst','--xml-strict-mode','--properties-array-brackets','--lua-globals','--lua-unquoted','--security-disable-env-ops','--security-disable-file-ops','--security-enable-system-operator','--header-preprocess','--string-interpolation','-c','--yaml-compact-seq-indent','--yaml-fix-merge-anchor-to-spec'):
            pass
        elif a in ('-r','--unwrapScalar'):
            opts.unwrap=True
        elif a.startswith('-r=') or a.startswith('--unwrapScalar='):
            opts.unwrap = a.split('=',1)[1].lower() not in ('false','0','no')
        elif a in ('-I','--indent'):
            opts.indent=int(needval())
        elif a.startswith('-I=') or a.startswith('--indent='):
            opts.indent=int(a.split('=',1)[1])
        elif a in ('-p','--input-format'):
            opts.input_format=needval()
        elif a.startswith('-p=') or a.startswith('--input-format='):
            opts.input_format=a.split('=',1)[1]
        elif a.startswith('-p') and len(a)>2:
            opts.input_format=a[2:]
        elif a in ('-o','--output-format'):
            opts.output_format=needval()
        elif a.startswith('-o=') or a.startswith('--output-format='):
            opts.output_format=a.split('=',1)[1]
        elif a.startswith('-o') and len(a)>2:
            opts.output_format=a[2:]
        elif a=='--expression':
            opts.expression=needval()
        elif a.startswith('--expression='):
            opts.expression=a.split('=',1)[1]
        elif a=='--from-file':
            opts.from_file=needval()
        elif a.startswith('--from-file='):
            opts.from_file=a.split('=',1)[1]
        elif a=='--properties-separator':
            opts.props_sep=needval()
        elif a.startswith('--properties-separator='):
            opts.props_sep=a.split('=',1)[1]
        elif a=='--shell-key-separator':
            opts.shell_sep=needval()
        elif a.startswith('--shell-key-separator='):
            opts.shell_sep=a.split('=',1)[1]
        elif a in ('--csv-separator','--xml-attribute-prefix','--xml-content-name','--xml-directive-name','--xml-proc-inst-prefix','--lua-prefix','--lua-suffix','-f','--front-matter','-s','--split-exp','--split-exp-file'):
