            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
        else:
            if c in ('"',"'"): quote=c
            elif c=='#' and (i==0 or line[i-1].isspace()):
                return line[:i].rstrip()
    return line.rstrip('\n\r')

def split_docs(text):
    docs=[]; cur=[]
    for raw in text.splitlines():
        if raw.strip() == '---':
            docs.append('\n'.join(cur)); cur=[]
        elif raw.strip() == '...':
            docs.append('\n'.join(cur)); cur=[]
        else:
            cur.append(raw)
    if cur or not docs:
        docs.append('\n'.join(cur))
    return docs

def prep_lines(text):
    lines=[]
    for raw in text.splitlines():
        if not raw.strip():
            continue
        st=raw.lstrip(' ')
        if st.startswith('#'):
            continue
        line=strip_comment(raw)
        if not line.strip():
            continue
        indent=len(line)-len(line.lstrip(' '))
        lines.append((indent,line.lstrip(' ')))
    return lines

def parse_scalar(s):
    s=s.strip()
    if s == '':
        return ''
    if s in ('null','Null','NULL','~'):
        return None
    if s == 'true' or s == 'True' or s == 'TRUE':
        return True
    if s == 'false' or s == 'False' or s == 'FALSE':
        return False
    if (s.startswith('"') and s.endswith('"')) or (s.startswith("'") and s.endswith("'")):
        try:
            if s[0]=='"':
                return json.loads(s)
            return s[1:-1].replace("''", "'")
        except Exception:
            return s[1:-1]
    if s.startswith('[') and s.endswith(']'):
        return parse_inline_list(s[1:-1])
    if s.startswith('{') and s.endswith('}'):
        return parse_inline_map(s[1:-1])
    if re.fullmatch(r'[+-]?\d+', s):
        try: return int(s)
        except Exception: pass
    if re.fullmatch(r'[+-]?(?:\d+\.\d*|\d*\.\d+)(?:[eE][+-]?\d+)?', s) or re.fullmatch(r'[+-]?\d+[eE][+-]?\d+', s):
        try: return float(s)
        except Exception: pass
    return s

def parse_inline_list(body):
    if body.strip()=='': return []
    return [parse_scalar(p) for p in split_top(body, ',')]

def parse_inline_map(body):
    d={}
    if body.strip()=='': return d
    for part in split_top(body, ','):
        k,v=split_key_value(part)
        if k is None:
            continue
        d[parse_key(k)] = parse_scalar(v)
    return d

def split_key_value(s):
    depth=0; quote=None; esc=False
    for i,c in enumerate(s):
        if quote:
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
        else:
            if c in ('"',"'"): quote=c
            elif c in '[{(': depth+=1
            elif c in ']})': depth-=1
            elif c==':' and depth==0:
                return s[:i].strip(), s[i+1:].strip()
    return None, None

def parse_key(k):
    k=k.strip()
    if (k.startswith('"') and k.endswith('"')) or (k.startswith("'") and k.endswith("'")):
        return str(parse_scalar(k))
    return k

def parse_yaml_doc(text):
    # JSON is valid YAML for common inputs; try it first when it looks JSON-ish.
    st=text.strip()
    if st == '':
        return None
    if st[0] in '[{':
        try: return json.loads(st)
        except Exception: pass
        try: return parse_scalar(st)
        except Exception: pass
    lines=prep_lines(text)
    if not lines:
        return None
    val, idx=parse_block(lines,0,lines[0][0])
    return val

def parse_block(lines, idx, indent):
    if idx>=len(lines): return None, idx
    if lines[idx][0] < indent: return None, idx
    if lines[idx][1].startswith('- ') and lines[idx][0]==indent:
        return parse_sequence(lines, idx, indent)
    return parse_mapping(lines, idx, indent)

def parse_mapping(lines, idx, indent):
    d={}
    while idx < len(lines):
        ind, txt=lines[idx]
        if ind < indent: break
        if ind > indent:
            break
        if txt.startswith('- '): break
        k,v = split_key_value(txt)
        if k is None:
            idx += 1; continue
        key=parse_key(k)
        if v == '' or v in ('|','>','|-','>-','|+','>+'):
            if v.startswith('|') or v.startswith('>'):
                idx += 1
                block=[]
                while idx < len(lines) and lines[idx][0] > indent:
                    block.append(lines[idx][1])
                    idx += 1
                sep='\n' if v.startswith('|') else ' '
                d[key]=sep.join(block)
            else:
                idx += 1
                if idx < len(lines) and lines[idx][0] > indent:
                    child, idx = parse_block(lines, idx, lines[idx][0])
                    d[key]=child
                else:
                    d[key]=None
        else:
            d[key]=parse_scalar(v)
            idx += 1
    return d, idx

def parse_sequence(lines, idx, indent):
    arr=[]
    while idx < len(lines):
        ind, txt=lines[idx]
        if ind != indent or not txt.startswith('- '):
            break
        content=txt[2:].strip()
        if content == '':
            idx += 1
            if idx < len(lines) and lines[idx][0] > indent:
                child, idx = parse_block(lines, idx, lines[idx][0])
                arr.append(child)
            else:
                arr.append(None)
        else:
            k,v=split_key_value(content)
            if k is not None and not (content.startswith('{') or content.startswith('[')):
                item={parse_key(k): parse_scalar(v) if v!='' else None}
                idx += 1
                if v=='':
                    if idx < len(lines) and lines[idx][0] > indent:
                        child, idx = parse_block(lines, idx, lines[idx][0])
                        item[parse_key(k)] = child
                # consume following mapping entries indented under this item
                while idx < len(lines) and lines[idx][0] > indent:
                    subind, subtxt=lines[idx]
                    if subtxt.startswith('- ') and subind==indent+2:
                        break
                    kk,vv=split_key_value(subtxt)
                    if kk is None: break
                    key=parse_key(kk)
                    if vv=='':
                        idx += 1
                        if idx < len(lines) and lines[idx][0] > subind:
                            child, idx = parse_block(lines, idx, lines[idx][0])
                        else:
                            child=None
                        item[key]=child
                    else:
                        item[key]=parse_scalar(vv); idx += 1
                arr.append(item)
            else:
                arr.append(parse_scalar(content)); idx += 1
    return arr, idx

def parse_yaml(text):
    return [parse_yaml_doc(d) for d in split_docs(text)]

# ----------------------------- other formats -----------------------------
def parse_json_text(text):
    st=text.strip()
    if st=='': return [None]
    # multiple JSON docs line-by-line if whole file fails
    try: return [json.loads(st)]
    except Exception:
        docs=[]
        for line in text.splitlines():
            if line.strip(): docs.append(json.loads(line))
        return docs or [None]

def auto_parse_cell(s):
    # CSV auto parse via yaml/json-style scalar
    return parse_scalar(s)

def parse_csv_text(text, sep=','):
    rdr=csv.reader(StringIO(text), delimiter=sep)
    rows=list(rdr)
    if not rows: return [[]]
    header=rows[0]
    out=[]
    for row in rows[1:]:
        if not row: continue
        d={}
        for i,h in enumerate(header):
            d[h]=auto_parse_cell(row[i]) if i < len(row) else ''
        out.append(d)
    return [out]

def set_path(root, parts, value):
    if root is None:
        root=[] if parts and isinstance(parts[0], int) else {}
    cur=root
    for i,p in enumerate(parts):
        last=i==len(parts)-1
        nxt = parts[i+1] if not last else None
        if isinstance(p, int):
            if not isinstance(cur, list):
                # cannot replace parent by reference here except caller ensures
                return root
            while len(cur) <= p: cur.append(None)
            if last:
                cur[p]=value
            else:
                if cur[p] is None or not isinstance(cur[p], (dict,list)):
                    cur[p] = [] if isinstance(nxt,int) else {}
                cur=cur[p]
        else:
            if not isinstance(cur, dict): return root
            if last:
                cur[p]=value
            else:
                if p not in cur or cur[p] is None or not isinstance(cur[p], (dict,list)):
                    cur[p] = [] if isinstance(nxt,int) else {}
                cur=cur[p]
    return root

def parse_props_text(text):
    root={}
    for raw in text.splitlines():
        line=raw.strip()
        if not line or line.startswith('#') or line.startswith('!'): continue
        if '=' in line:
            k,v=line.split('=',1)
        elif ':' in line:
            k,v=line.split(':',1)
        else:
            continue
        key=k.strip(); val=v.strip()
        parts=[]
        for p in key.split('.'):
            if p.isdigit(): parts.append(int(p))
            elif re.fullmatch(r'.+\[\d+\]', p):
                name=p[:p.rfind('[')]; idx=int(p[p.rfind('[')+1:-1]); parts.extend([name,idx])
            else: parts.append(p)
        # create arrays when numeric next: conversion pass simpler
        root=set_path_smart(root, parts, val)
    return [root]

def set_path_smart(root, parts, value):
    # rebuild with dict/list awareness
    def rec(cur, ps):
        if not ps: return value
        p=ps[0]
        if isinstance(p,int):
            arr = cur if isinstance(cur,list) else []
            while len(arr)<=p: arr.append(None)
            arr[p]=rec(arr[p], ps[1:])
            return arr
        else:
            d = cur if isinstance(cur,dict) else {}
            d[p]=rec(d.get(p), ps[1:])
            return d
    return rec(root, parts)

def parse_ini_text(text):
    root={}; section=None
    for raw in text.splitlines():
        line=raw.strip()
        if not line or line.startswith(';') or line.startswith('#'): continue
        if line.startswith('[') and line.endswith(']'):
            section=line[1:-1].strip(); root.setdefault(section,{})
        elif '=' in line or ':' in line:
            sep='=' if '=' in line else ':'
            k,v=line.split(sep,1); k=k.strip(); v=v.strip()
            if section: root.setdefault(section,{})[k]=v
            else: root[k]=v
    return [root]

def parse_toml_text(text):
    root={}; cur=root
    for raw in text.splitlines():
        line=strip_comment(raw).strip()
        if not line: continue
        if line.startswith('[') and line.endswith(']'):
            parts=[p.strip() for p in line[1:-1].split('.')]
            cur=root
            for p in parts:
                cur=cur.setdefault(p,{})
        elif '=' in line:
            k,v=line.split('=',1); cur[k.strip()]=parse_scalar(v.strip())
    return [root]

def elem_to_obj(el):
    children=list(el)
    attrs={'+@'+k:v for k,v in el.attrib.items()}
    text=(el.text or '').strip()
    if not children and not attrs:
        return text
    d={}
    if text:
        d['+content']=text
    for k,v in attrs.items(): d[k]=v
    groups={}
    for ch in children:
        groups.setdefault(ch.tag,[]).append(elem_to_obj(ch))
    for k,vals in groups.items():
        d[k]=vals[0] if len(vals)==1 else vals
    return d

def parse_xml_text(text):
    root_el=ET.fromstring(text.strip())
    return [{root_el.tag: elem_to_obj(root_el)}]

def parse_input(text, fmt, filename=None):
    f=(fmt or 'auto').lower()
    aliases={'y':'yaml','a':'auto','j':'json','p':'props','c':'csv','t':'tsv','x':'xml','h':'hcl','l':'lua','i':'ini'}
    f=aliases.get(f,f)
    if f=='auto':
        ext=os.path.splitext(filename or '')[1].lower()
        f={'.json':'json','.csv':'csv','.tsv':'tsv','.xml':'xml','.properties':'props','.props':'props','.toml':'toml','.ini':'ini'}.get(ext,'yaml')
    if f in ('yaml','kyaml'):
        return parse_yaml(text)
    if f=='json': return parse_json_text(text)
    if f=='csv': return parse_csv_text(text, ',')
    if f=='tsv': return parse_csv_text(text, '\t')
    if f in ('props','properties'): return parse_props_text(text)
    if f=='xml': return parse_xml_text(text)
    if f=='ini': return parse_ini_text(text)
    if f in ('toml','hcl'): return parse_toml_text(text)
    if f=='base64': return [base64.b64decode(text.strip()).decode()]
    if f=='uri': return [urllib.parse.unquote_plus(text.strip())]
    return parse_yaml(text)

# ----------------------------- output -----------------------------
def scalar_to_string(v, quote_for_yaml=False):
    if v is None: return 'null'
    if v is True: return 'true'
    if v is False: return 'false'
    if isinstance(v,(int,float)): return str(v).lower()
    s=str(v)
    if quote_for_yaml:
        if s=='' or s in ('true','false','null','Null','NULL','~') or is_num_str(s) or ': ' in s or ' #' in s or s[0:1] in ['@','`','&','*','!','|','>','{','}','[',']',',']:
            return json.dumps(s)
    return s

def yaml_lines(v, indent=0, step=2):
    sp=' '*indent
    if isinstance(v, dict):
        if not v: return [sp+'{}']
        lines=[]
        for k,val in v.items():
            key=str(k)
            if isinstance(val,(dict,list)):
                if isinstance(val, (dict,list)) and len(val)==0:
                    lines.append(f'{sp}{key}: ' + ('{}' if isinstance(val,dict) else '[]'))
                else:
                    lines.append(f'{sp}{key}:')
                    lines.extend(yaml_lines(val, indent+step, step))
            else:
                lines.append(f'{sp}{key}: {scalar_to_string(val, True)}')
        return lines
    if isinstance(v, list):
        if not v: return [sp+'[]']
        lines=[]
        for item in v:
            if isinstance(item, dict):
                if not item:
                    lines.append(sp+'- {}')
                else:
                    first=True
                    for k,val in item.items():
                        if first:
                            if isinstance(val,(dict,list)):
                                lines.append(f'{sp}- {k}:')
                                lines.extend(yaml_lines(val, indent+step, step))
                            else:
                                lines.append(f'{sp}- {k}: {scalar_to_string(val, True)}')
                            first=False
                        else:
                            if isinstance(val,(dict,list)):
                                lines.append(f'{sp}{" "*step}{k}:')
                                lines.extend(yaml_lines(val, indent+2*step, step))
                            else:
                                lines.append(f'{sp}{" "*step}{k}: {scalar_to_string(val, True)}')
            elif isinstance(item, list):
                lines.append(sp+'-')
                lines.extend(yaml_lines(item, indent+step, step))
            else:
                lines.append(f'{sp}- {scalar_to_string(item, True)}')
        return lines
    return [sp+scalar_to_string(v, False)]

def dump_yaml(v, indent=2):
    return '\n'.join(yaml_lines(v,0,indent))

def flatten(v, prefix='', sep='.'):
    rows=[]
    if isinstance(v, dict):
        for k,val in v.items():
            p=f'{prefix}{sep}{k}' if prefix else str(k)
            rows.extend(flatten(val,p,sep))
    elif isinstance(v, list):
        for i,val in enumerate(v):
            p=f'{prefix}{sep}{i}' if prefix else str(i)
            rows.extend(flatten(val,p,sep))
    else:
        rows.append((prefix, scalar_to_string(v)))
    return rows

def dump_props(v, sepstr=' = '):
    return '\n'.join(k+sepstr+val for k,val in flatten(v,'.'.join([]),'.'))

def dump_shell(v, keysep='_'):
    return '\n'.join(k.replace('.',keysep)+'='+shell_quote_value(val) for k,val in flatten(v,'','.'))

def shell_quote_value(s):
    s=str(s)
    if re.fullmatch(r'[A-Za-z0-9_./:@%+-]*', s): return s
    return "'" + s.replace("'", "'\\''") + "'"

def dump_csv(v, sep=','):
    arr=v if isinstance(v,list) else [v]
    if not arr: return ''
    if all(isinstance(x,dict) for x in arr):
        headers=[]
        for row in arr:
            for k in row.keys():
                if k not in headers: headers.append(k)
        sio=StringIO(); w=csv.writer(sio, delimiter=sep, lineterminator='\n')
        w.writerow(headers)
        for row in arr:
            w.writerow([scalar_to_string(row.get(h,'')) for h in headers])
        return sio.getvalue().rstrip('\n')
    sio=StringIO(); w=csv.writer(sio, delimiter=sep, lineterminator='\n')
    for item in arr: w.writerow([scalar_to_string(item)])
    return sio.getvalue().rstrip('\n')

def xml_escape(s):
    return str(s).replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')

def dump_xml(v, name=None, indent=0):
    sp=' '*indent
    lines=[]
    if name is None:
        if isinstance(v,dict):
            for k,val in v.items(): lines.extend(dump_xml(val,k,indent))
        elif isinstance(v,list):
            for item in v: lines.extend(dump_xml(item,'item',indent))
        else:
            lines.append(xml_escape(scalar_to_string(v)))
        return lines
    if isinstance(v,list):
        for item in v: lines.extend(dump_xml(item,name,indent))
    elif isinstance(v,dict):
        attrs=''; content=None; children=[]
        for k,val in v.items():
            if str(k).startswith('+@'):
                attrs += f' {k[2:]}="{xml_escape(val)}"'
            elif k=='+content':
                content=scalar_to_string(val)
            else:
                children.extend(dump_xml(val,k,indent+2))
        if children:
            lines.append(f'{sp}<{name}{attrs}>')
            if content: lines.append(' '*(indent+2)+xml_escape(content))
            lines.extend(children)
            lines.append(f'{sp}</{name}>')
        else:
            text=xml_escape(content or '')
            lines.append(f'{sp}<{name}{attrs}>{text}</{name}>')
    else:
        lines.append(f'{sp}<{name}>{xml_escape(scalar_to_string(v))}</{name}>')
    return lines

def lua_val(v, level=0):
    tab='\t'*level
    if isinstance(v,dict):
        lines=['{']
        for k,val in v.items():
            rendered=lua_val(val, level+1)
            if '\n' in rendered:
                lines.append('\t'*(level+1)+f'[{json.dumps(str(k))}] = '+rendered+';')
            else:
                lines.append('\t'*(level+1)+f'[{json.dumps(str(k))}] = {rendered};')
        lines.append(tab+'}')
        return '\n'.join(lines)
    if isinstance(v,list):
        lines=['{']
        for item in v:
            rendered=lua_val(item, level+1)
            lines.append('\t'*(level+1)+rendered+',')
        lines.append(tab+'}')
        return '\n'.join(lines)
    if isinstance(v,str): return json.dumps(v)
    if v is True: return 'true'
    if v is False: return 'false'
    if v is None: return 'nil'
    return str(v)

def dump_one(v, fmt, indent=2, unwrap=True, props_sep=' = ', shell_sep='_'):
    f=fmt.lower()
    aliases={'y':'yaml','j':'json','p':'props','c':'csv','t':'tsv','x':'xml','s':'shell','l':'lua','i':'ini'}
    f=aliases.get(f,f)
    if f in ('yaml','kyaml'):
        if not isinstance(v,(dict,list)) and unwrap:
            return scalar_to_string(v, False)
        return dump_yaml(v, indent)
    if f=='json': return json.dumps(v, indent=indent)
    if f in ('props','properties','ini'): return dump_props(v, props_sep)
    if f=='shell': return dump_shell(v, shell_sep)
    if f=='csv': return dump_csv(v, ',')
    if f=='tsv': return dump_csv(v, '\t')
    if f=='xml': return '\n'.join(dump_xml(v))
    if f=='base64': return base64.b64encode(scalar_to_string(v).encode()).decode()
    if f=='uri': return urllib.parse.quote_plus(scalar_to_string(v))
    if f=='lua': return 'return '+lua_val(v)+';'
    return dump_yaml(v, indent)

# ----------------------------- expression evaluation -----------------------------
def parse_path(path):
    s=path.strip()
    if s == '.': return []
    if not s.startswith('.'):
        raise YQError('bad expression')
    parts=[]; i=1; key=''
    while i < len(s):
        c=s[i]
        if c=='.':
            if key!='': parts.append(key); key=''
            i+=1
        elif c=='[':
            if key!='': parts.append(key); key=''
            j=s.find(']',i)
            if j<0: raise YQError('bad expression, could not find matching `]`')
            inside=s[i+1:j].strip()
            if inside=='': parts.append('*')
            elif (inside.startswith('"') and inside.endswith('"')) or (inside.startswith("'") and inside.endswith("'")):
                parts.append(str(parse_scalar(inside)))
            elif re.fullmatch(r'-?\d+', inside): parts.append(int(inside))
            else: parts.append(inside)
            i=j+1
        else:
            key+=c; i+=1
    if key!='': parts.append(key)
    return parts

def get_path_values(data, parts):
    vals=[data]
    for p in parts:
        new=[]
        for v in vals:
            if p=='*':
                if isinstance(v,list): new.extend(v)
                elif isinstance(v,dict): new.extend(v.values())
            elif isinstance(p,int):
                if isinstance(v,list) and -len(v) <= p < len(v): new.append(v[p])
                else: new.append(None)
            else:
                if isinstance(v,dict) and p in v: new.append(v[p])
                else: new.append(None)
        vals=new
    return vals

def assign_path(data, path, value):
    parts=parse_path(path)
    if data is None:
        data=[] if parts and isinstance(parts[0],int) else {}
    return set_path_smart(data, parts, value)

def delete_path(data, path):
    data=copy.deepcopy(data); parts=parse_path(path)
    def rec(cur, ps):
        if not ps: return
        p=ps[0]
        if len(ps)==1:
            if isinstance(cur,dict) and p in cur: del cur[p]
            elif isinstance(cur,list) and isinstance(p,int) and 0<=p<len(cur): del cur[p]
        else:
            if isinstance(cur,dict): rec(cur.get(p), ps[1:])
            elif isinstance(cur,list) and isinstance(p,int) and 0<=p<len(cur): rec(cur[p], ps[1:])
    rec(data, parts); return data

def deep_merge(a,b):
    if isinstance(a,dict) and isinstance(b,dict):
        out=copy.deepcopy(a)
        for k,v in b.items(): out[k]=deep_merge(out[k],v) if k in out else copy.deepcopy(v)
        return out
    return copy.deepcopy(b)

def eval_expr(expr, data, opts=None):
    expr=strip_outer_parens(expr.strip())
    if expr=='': return [data]
    # Special eval-all merge idiom
    if 'ireduce' in expr and '*' in expr and isinstance(data, list) and getattr(opts,'eval_all',False):
        acc={}
        for d in data: acc=deep_merge(acc,d)
        return [acc]
    stages=split_top(expr, '|')
    vals=[data]
    for st in stages:
        if st=='': continue
        nextvals=[]
        for v in vals:
            nextvals.extend(eval_stage(st, v, opts))
        vals=nextvals
    return vals

def eval_stage(expr, data, opts=None):
    expr=strip_outer_parens(expr.strip())
    # assignment, top-level = but not comparisons
    pos,op=find_assignment(expr)
    if pos>=0:
        left=expr[:pos].strip(); right=expr[pos+1:].strip()
        vals=eval_expr(right, data, opts)
        val=vals[0] if vals else None
        d=copy.deepcopy(data)
        return [assign_path(d, left, val)]
    # comparisons
    for ops in [['==','!=','>=','<='], ['>','<']]:
        pos,op=find_top_op(expr, ops)
        if pos>=0:
            a=first(eval_expr(expr[:pos], data, opts)); b=first(eval_expr(expr[pos+len(op):], data, opts))
            return [compare(a,b,op)]
    # addition/subtraction after comparisons
    pos,op=find_top_arith(expr, ['+','-'])
    if pos>=0:
        a=first(eval_expr(expr[:pos], data, opts)); b=first(eval_expr(expr[pos+1:], data, opts))
        try:
            if op=='+': return [a+b]
            return [a-b]
        except Exception:
            return [str(a)+str(b) if op=='+' else None]
    pos,op=find_top_arith(expr, ['*','/'])
    if pos>=0:
        a=first(eval_expr(expr[:pos], data, opts)); b=first(eval_expr(expr[pos+1:], data, opts))
        if op=='*':
            if isinstance(a,dict) and isinstance(b,dict): return [deep_merge(a,b)]
            try: return [a*b]
            except Exception: return [None]
        else:
            try: return [a/b]
            except Exception: return [None]
    # functions/stages
    if expr=='length':
        return [len(data) if data is not None and hasattr(data,'__len__') else 0]
    if expr=='keys':
        if isinstance(data,dict): return [list(data.keys())]
        if isinstance(data,list): return [list(range(len(data)))]
        return [[]]
    if expr.startswith('select(') and expr.endswith(')'):
        cond=first(eval_expr(expr[7:-1], data, opts))
        return [data] if truthy(cond) else []
    if expr.startswith('map(') and expr.endswith(')'):
        inner=expr[4:-1]
        if isinstance(data,list): return [[first(eval_expr(inner, item, opts)) for item in data]]
        return [[]]
    if expr.startswith('has(') and expr.endswith(')'):
        key=first(eval_expr(expr[4:-1], data, opts))
        if isinstance(data,dict): return [str(key) in data]
        if isinstance(data,list) and isinstance(key,int): return [0<=key<len(data)]
        return [False]
    if expr.startswith('del(') and expr.endswith(')'):
        return [delete_path(data, expr[4:-1].strip())]
    if expr.startswith('load(') and expr.endswith(')'):
        fn=first(eval_expr(expr[5:-1], data, opts))
        with open(fn,'r') as f: txt=f.read()
        fmt='auto'
        return [parse_input(txt, fmt, fn)[0]]
    if expr.startswith('strenv(') and expr.endswith(')'):
        name=expr[7:-1].strip()
        return [os.environ.get(name,'')]
    if expr.startswith('env(') and expr.endswith(')'):
        name=expr[4:-1].strip()
        return [parse_scalar(os.environ.get(name,''))]
    # collection/literals
    if expr.startswith('[') and expr.endswith(']'):
        inner=expr[1:-1].strip()
        if inner=='': return [[]]
        # JSON/YAML literal if comma separated and not an expression-ish collection
        if '|' not in inner and not inner.lstrip().startswith('.') and ',' in inner:
            return [[first(eval_expr(p, data, opts)) for p in split_top(inner, ',')]]
        if '|' not in inner and not inner.lstrip().startswith('.'):
            try: return [parse_scalar(expr)]
            except Exception: pass
        return [eval_expr(inner, data, opts)]
    if expr.startswith('{') and expr.endswith('}'):
        # yq requires quoted JSON-like keys for this simplified implementation
        try: return [json.loads(expr)]
        except Exception:
            return [parse_inline_map(expr[1:-1])]
    if (expr.startswith('"') and expr.endswith('"')) or (expr.startswith("'") and expr.endswith("'")):
        return [parse_scalar(expr)]
    if expr in ('true','false','null') or is_num_str(expr):
        return [parse_scalar(expr)]
    if expr=='.': return [data]
    if expr.startswith('.'):
        return get_path_values(data, parse_path(expr))
    # bare env variable? string fallback
    return [expr]

def first(vals):
    if isinstance(vals, list): return vals[0] if vals else None
    return vals

def truthy(v):
    return not (v is False or v is None)

def compare(a,b,op):
    if op=='==': return a==b
    if op=='!=': return a!=b
    try:
        if op=='>': return a>b
        if op=='<': return a<b
        if op=='>=': return a>=b
        if op=='<=': return a<=b
    except Exception:
        return False

def find_assignment(s):
    depth=0; quote=None; esc=False
    for i,c in enumerate(s):
        if quote:
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
        else:
            if c in ('"',"'"): quote=c
            elif c in '[{(': depth+=1
            elif c in ']})': depth-=1
            elif c=='=' and depth==0:
                prev=s[i-1] if i>0 else ''; nxt=s[i+1] if i+1<len(s) else ''
                if prev not in ['=','!','<','>'] and nxt!='=':
                    return i,'='
    return -1,None

def find_top_arith(s, ops):
    depth=0; quote=None; esc=False
    for i in range(len(s)-1, -1, -1):
        c=s[i]
        if quote:
            # reverse scan quote handling is hard; use forward collect positions instead
            pass
    depth=0; quote=None; esc=False; found=[]
    for i,c in enumerate(s):
        if quote:
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
        else:
            if c in ('"',"'"): quote=c
            elif c in '[{(': depth+=1
            elif c in ']})': depth-=1
            elif depth==0 and c in ops:
                if c in '+-' and (i==0 or s[i-1] in ' ([{:+-*/'):
                    continue
                found.append((i,c))
    return found[-1] if found else (-1,None)

# ----------------------------- CLI -----------------------------
class Opts:
    pass

def root_help():
    return f'''yq is a portable command-line data file processor (https://github.com/mikefarah/yq/) 
See https://mikefarah.gitbook.io/yq/ for detailed documentation and examples.

Usage:
  yq [flags]
  yq [command]

Examples:

# yq tries to auto-detect the file format based off the extension, and defaults to YAML if it's unknown (or piping through STDIN)
# Use the '-p/--input-format' flag to specify a format type.
cat file.xml | yq -p xml

# read the "stuff" node from "myfile.yml"
yq '.stuff' < myfile.yml

# update myfile.yml in place
yq -i '.stuff = "foo"' myfile.yml

# print contents of sample.json as idiomatic YAML
yq -P -oy sample.json

Available Commands:
  completion  Generate the autocompletion script for the specified shell
  eval        (default) Apply the expression to each document in each yaml file in sequence
  eval-all    Loads _all_ yaml documents of _all_ yaml files and runs expression once
  help        Help about any command

Flags:
  -C, --colors                            force print with colors
  -M, --no-colors                         force print with no colors
  -e, --exit-status                       set exit status if there are no matches or null or false is returned
  -h, --help                              help for yq
  -I, --indent int                        sets indent level for output (default 2)
  -i, --inplace                           update the file in place of first file given.
  -n, --null-input                        Don't read input, simply evaluate the expression given.
  -o, --output-format string              [auto|yaml|json|props|csv|tsv|xml|shell|lua|ini|base64|uri] output format type. (default "auto")
  -p, --input-format string               [auto|yaml|json|props|csv|tsv|xml|base64|uri|toml|hcl|lua|ini] parse format for input. (default "auto")
  -P, --prettyPrint                       pretty print
  -r, --unwrapScalar                      unwrap scalar (default true)
  -V, --version                           Print version information and quit
'''

def eval_help():
    return '''Usage:
  yq eval [expression] [yaml_file1]... [flags]

Aliases:
  eval, e

Examples:

# Reads field under the given path for each file
yq e '.a.b' f1.yml f2.yml 

# Prints out the file
yq e sample.yaml 

# Pipe from STDIN
## use '-' as a filename to pipe from STDIN
cat file2.yml | yq e '.a.b' file1.yml - file3.yml

Flags:
  -h, --help   help for eval
'''

def completion(shell):
    if shell in ('bash','zsh','fish','powershell'):
        return f'# {shell} completion for yq\n'
    raise YQError('unknown shell')

def parse_args(argv):
    opts=Opts(); opts.input_format='auto'; opts.output_format='auto'; opts.indent=2; opts.inplace=False
    opts.null_input=False; opts.no_doc=False; opts.nul=False; opts.exit_status=False; opts.unwrap=True
    opts.expression=None; opts.from_file=None; opts.eval_all=False; opts.props_sep=' = '; opts.shell_sep='_'
    opts.command=None; opts.files=[]; positionals=[]
    i=0
    if argv and argv[0] in ('eval','e','eval-all','ea'):
        opts.command=argv[0]; opts.eval_all=argv[0] in ('eval-all','ea'); i=1
    elif argv and argv[0]=='help':
        opts.command='help'; positionals=argv[1:]; i=len(argv)
    elif argv and argv[0]=='completion':
        opts.command='completion'; positionals=argv[1:]; i=len(argv)
    while i < len(argv):
        a=argv[i]
        def needval():
            nonlocal i
            if i+1>=len(argv): raise YQError('flag needs an argument: '+a)
            i+=1; return argv[i]
        if a in ('-h','--help'):
            opts.command='helpflag'
        elif a in ('-V','--version'):
            opts.version=True
        elif a in ('-i','--inplace'):
            opts.inplace=True
        elif a in ('-n','--null-input'):
            opts.null_input=True
        elif a in ('-N','--no-doc'):
            opts.no_doc=True
        elif a in ('-0','--nul-output'):
            opts.nul=True
        elif a in ('-e','--exit-status'):
            opts.exit_status=True
        elif a in ('-P','--prettyPrint','--prettyprint'):
            pass
        elif a in ('-C','--colors','-M','--no-colors','-v','--verbose','--debug-node-info','--csv-auto-parse','--tsv-auto-parse','--xml-keep-namespace','--xml-raw-token','--xml-skip-directives','--xml-skip-proc-inst','--xml-strict-mode','--properties-array-brackets','--lua-globals','--lua-unquoted','--security-disable-env-ops','--security-disable-file-ops','--security-enable-system-operator','--header-preprocess','--string-interpolation','-c','--yaml-compact-seq-indent','--yaml-fix-merge-anchor-to-spec'):
            pass
        elif a in ('-r','--unwrapScalar'):
            opts.unwrap=True
        elif a.startswith('-r=') or a.startswith('--unwrapScalar='):
            opts.unwrap = a.split('=',1)[1].lower() not in ('false','0','no')
        elif a in ('-I','--indent'):
            opts.indent=int(needval())
        elif a.startswith('-I=') or a.startswith('--indent='):
            opts.indent=int(a.split('=',1)[1])
        elif a in ('-p','--input-format'):
            opts.input_format=needval()
        elif a.startswith('-p=') or a.startswith('--input-format='):
            opts.input_format=a.split('=',1)[1]
        elif a.startswith('-p') and len(a)>2:
            opts.input_format=a[2:]
        elif a in ('-o','--output-format'):
            opts.output_format=needval()
        elif a.startswith('-o=') or a.startswith('--output-format='):
            opts.output_format=a.split('=',1)[1]
        elif a.startswith('-o') and len(a)>2:
            opts.output_format=a[2:]
        elif a=='--expression':
            opts.expression=needval()
        elif a.startswith('--expression='):
            opts.expression=a.split('=',1)[1]
        elif a=='--from-file':
            opts.from_file=needval()
        elif a.startswith('--from-file='):
            opts.from_file=a.split('=',1)[1]
        elif a=='--properties-separator':
            opts.props_sep=needval()
        elif a.startswith('--properties-separator='):
            opts.props_sep=a.split('=',1)[1]
        elif a=='--shell-key-separator':
            opts.shell_sep=needval()
        elif a.startswith('--shell-key-separator='):
            opts.shell_sep=a.split('=',1)[1]
        elif a in ('--csv-separator','--xml-attribute-prefix','--xml-content-name','--xml-directive-name','--xml-proc-inst-prefix','--lua-prefix','--lua-suffix','-f','--front-matter','-s','--split-exp','--split-exp-file'):
            needval()
        elif a.startswith('--') or (a.startswith('-') and a!='-'):
            raise YQError('unknown flag: '+a)
        else:
            positionals.append(a)
        i+=1
    if getattr(opts,'version',False): return opts, positionals
    if opts.from_file:
        with open(opts.from_file) as f: opts.expression=f.read()
    # expression detection
    if opts.expression is None and positionals:
        firstpos=positionals[0]
        if opts.null_input:
            opts.expression=firstpos; opts.files=positionals[1:]
        elif looks_like_expression(firstpos) or len(positionals)>1:
            opts.expression=firstpos; opts.files=positionals[1:]
        else:
            opts.expression='.'; opts.files=positionals
    else:
        opts.files=positionals
    if opts.expression is None: opts.expression='.'
    return opts, positionals

def looks_like_expression(s):
    st=s.strip()
    return st.startswith('.') or st.startswith('[') or st.startswith('{') or st.startswith('load(') or st.startswith('env(') or st.startswith('strenv(') or st in ('true','false','null') or bool(re.fullmatch(r'[+-]?\d+(?:\.\d+)?',st)) or any(op in st for op in ['|','=','select(','del(','has(','length','keys'])

def read_file(fn, opts):
    if fn=='-':
        txt=sys.stdin.read(); filename=None
    else:
        with open(fn,'r') as f: txt=f.read()
        filename=fn
    return parse_input(txt, opts.input_format, filename), filename

def choose_output_format(opts, input_filename=None):
    f=opts.output_format.lower()
    if f!='auto':
        return f
    # auto uses file extension for regular files; stdin/default yaml
    ext=os.path.splitext(input_filename or '')[1].lower()
    return {'.json':'json','.csv':'csv','.tsv':'tsv','.xml':'xml','.properties':'props','.props':'props'}.get(ext,'yaml')

def main(argv):
    try:
        opts, pos=parse_args(argv)
        if getattr(opts,'version',False):
            print(f'yq (https://github.com/mikefarah/yq/) version {VERSION}')
            return 0
        if opts.command=='completion':
            shell=pos[0] if pos else 'bash'; sys.stdout.write(completion(shell)); return 0
        if opts.command in ('help','helpflag'):
            if opts.command=='helpflag' and (pos and pos[0] in ('eval','e')):
                sys.stdout.write(eval_help()); return 0
            sys.stdout.write(root_help() if not pos or pos[0] not in ('eval','e','eval-all','ea') else eval_help()); return 0
        if not argv and sys.stdin.isatty():
            sys.stdout.write(root_help()); return 0
        if opts.null_input:
            input_docs=[None]
            input_filename=None
        else:
            input_docs=[]; input_filename=None
            files=opts.files
            if not files:
                txt=sys.stdin.read()
                if txt=='':
                    sys.stdout.write(root_help()); return 0
                input_docs=parse_input(txt, opts.input_format, None); input_filename=None
            else:
                for fn in files:
                    docs, filename=read_file(fn, opts)
                    if input_filename is None: input_filename=filename
                    input_docs.extend(docs)
        if opts.eval_all:
            results=eval_expr(opts.expression, input_docs, opts)
        else:
            results=[]
            for d in input_docs:
                results.extend(eval_expr(opts.expression, d, opts))
        outfmt=choose_output_format(opts, input_filename)
        if opts.inplace:
            if not opts.files or opts.files[0]=='-':
                raise YQError('write in place flag only applicable when giving an expression and at least one file')
            text=render_results(results, outfmt, opts)
            with open(opts.files[0], 'w') as f: f.write(text + ('' if text.endswith('\n') or opts.nul else '\n'))
            return 0
        text=render_results(results, outfmt, opts)
        if text:
            sys.stdout.write(text)
            if not opts.nul and not text.endswith('\n'):
                sys.stdout.write('\n')
        # exit status
        if opts.exit_status:
            bad = (not results) or any(r is None or r is False for r in results)
            if bad:
                eprint('Error: no matches found')
                return 1
        return 0
    except FileNotFoundError as ex:
        eprint(f'Error: open {ex.filename}: no such file or directory'); return 1
    except YQError as ex:
        eprint('Error:', str(ex)); return 1
    except Exception as ex:
        eprint('Error:', str(ex)); return 1

def render_results(results, outfmt, opts):
    sep='\0' if opts.nul else '\n'
    chunks=[]
    for i,r in enumerate(results):
        if i>0 and outfmt in ('yaml','y','auto') and not opts.no_doc and not opts.nul and isinstance(r,(dict,list)):
            # yq generally separates multiple document results for YAML; scalar multi-doc handled below too.
            pass
        chunks.append(dump_one(r, outfmt, opts.indent, opts.unwrap, opts.props_sep, opts.shell_sep))
    if opts.nul: return '\0'.join(chunks) + ('\0' if chunks else '')
    if outfmt in ('yaml','y','kyaml') and len(chunks)>1 and not opts.no_doc:
        return ('\n---\n').join(chunks)
    return sep.join(chunks)

if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
